import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import AdCategoryService from "services/AdCategoryService";
import AdCategoryMockData from "mock/data/adCategoryData";
import { ADVERTISEMENT_ALL_CATEGORY_MOCK_API } from "configs/MockConfig";

const initialState = {
  loading: false,
  adCategories: [],
  filteredAdCategories: [],
  searchTerm: "",
  responseData: null,
  selectedAdCategory: null,
  responseMessage: null,
  selectedCategoryId: null,
  error: null,
  message: null,
  subPagination: {},
  pagination: {},
  editable_status: null,
  validationStatus: false,
  ValidateData: null,
  adCategoryValidationDialogVisible: false,
  singleCategory: null,
  responseImpactData: null,
  warningPagination: { size: 10, page: 1 },
  editItemId: null,
};

export const addAdCategory = createAsyncThunk(
  "adCategory/add",
  async ({ data, action }, { rejectWithValue }) => {
    try {
      console.log("Request Data:", data);
      console.log("Action Type:", action);
      const response = await AdCategoryService.addAdCategory(data, action);
      console.log("Response:", response);
      return response;
    } catch (err) {
      console.log("Error:", err);
      const errorMessage =
        err.response?.data?.message || "Failed to add category";
      return rejectWithValue(errorMessage);
    }
  }
);
export const validateAdCategory = createAsyncThunk(
  "adCategory/validation",
  async (adCategoryId, { rejectWithValue }) => {
    try {
      const response = await AdCategoryService.validateAdCategory(adCategoryId);

      return response;
    } catch (error) {
      return rejectWithValue(error.message || "Failed to fetch places");
    }
  }
);

export const updateAdCategory = createAsyncThunk(
  "adCategory/edit",
  async ({ data, action, pageData }, { rejectWithValue }) => {
    try {
      const response = await AdCategoryService.updateAdCategory(
        data,
        action,
        pageData
      );
      return response;
    } catch (error) {
      return rejectWithValue(error.message || "Failed to update category");
    }
  }
);

export const updateAdCategoryStatus = createAsyncThunk(
  "adCategoryStatus/edit",
  async ({ data, action, pageData }, { rejectWithValue }) => {
    try {
      const response = await AdCategoryService.updateAdStatus(
        data,
        action,
        pageData
      );
      return response;
    } catch (error) {
      return rejectWithValue(error.message || "Failed to edit event");
    }
  }
);

export const fetchAdCategories = createAsyncThunk(
  "adCategory/fetchAdCategories",
  async (pageData, { rejectWithValue }) => {
    try {
      if (ADVERTISEMENT_ALL_CATEGORY_MOCK_API) {
        const response = AdCategoryMockData.fetchAllCategory;
        return response.data;
      } else {
        const response = await AdCategoryService.fetchAdCategory(pageData);
        console.log("-----------Fetching categories", response.data[0]);
        return response.data[0];
      }
    } catch (error) {
      console.log(error, "-------------");
      return rejectWithValue("Failed to fetch categories");
    }
  }
);

const AdcategorySlice = createSlice({
  name: "adCategory",
  initialState,
  reducers: {
    setAdCategoryDialogVisible(state, action) {
      state.dialogVisible = action.payload;
    },
    setAdCategoryModalLoading(state, action) {
      state.modalLoading = action.payload;
    },
    setSelectedAdCategory(state, action) {
      state.selectedAdCategory = action.payload;
    },
    setEditItemId: (state, action) => {
      state.editItemId = action.payload;
    },
    filterCategory: (state, action) => {
      const { searchTerm, type } = action.payload;

      if (type === "category") {
        state.filteredAdCategories = state.adCategories.filter((category) =>
          category.name.toLowerCase().includes(searchTerm.toLowerCase())
        );
      }
    },

    setSearchTerm: (state, action) => {
      state.searchTerm = action.payload;
      state.filteredAdCategories = state.adCategories.filter((cat) =>
        cat.name.toLowerCase().includes(action.payload.toLowerCase())
      );
    },
    setAdCategoryValidationDialogVisible(state, action) {
      state.adCategoryValidationDialogVisible = action.payload;
    },
  },
  extraReducers: (builder) => {
    builder

      .addCase(validateAdCategory.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(validateAdCategory.fulfilled, (state, { payload }) => {
        state.loading = false;
        console.log("HELOOOOOOOOOO");

        if (payload.message === "warning") {
          state.validationStatus = false;
          state.message = payload.status.message;
          state.ValidateData = payload.status?.data;
          console.log(payload.status?.data, "DATAAAAAAA IN PAYLOAD");
          state.editable_status = payload.status?.editable_status;
        } else if (payload.data) {
          state.validationStatus = payload.data[0].validation_status;
          if (payload.status) {
            state.message = payload.status.message;
          }
        }
      })
      .addCase(validateAdCategory.rejected, (state, { payload }) => {
        state.loading = false;
        state.error = payload || "Failed to validate place";
      })
      .addCase(addAdCategory.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(addAdCategory.fulfilled, (state, action) => {
        state.loading = false;
        state.error = null;
        state.responseData = action.payload.data;
        state.responseMessage = action.payload.status.message;
      })
      .addCase(addAdCategory.rejected, (state, { payload }) => {
        state.loading = false;
        state.error = payload || "Failed to create category";
      })
      .addCase(fetchAdCategories.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchAdCategories.fulfilled, (state, { payload }) => {
        state.loading = false;
        state.adCategories = payload.items;
        state.filteredAdCategories = payload.items;
        state.pagination = payload;
      })
      .addCase(fetchAdCategories.rejected, (state, { payload }) => {
        state.loading = false;
        state.error = payload;
      })
      .addCase(updateAdCategory.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(updateAdCategory.fulfilled, (state, { payload }) => {
        state.loading = false;
        state.responseData = payload.data;
        if (payload.status) {
          state.message = payload.status.message;
          state.responseImpactData = payload.status.data?.active_schedules;
          state.editable_status = payload.status?.editable_status;
          state.warningPagination = payload.status?.data?.active_schedules;
        }
      })
      .addCase(updateAdCategory.rejected, (state, { payload }) => {
        state.loading = false;
        state.error = payload || "Failed to edit event";
      })
      .addCase(updateAdCategoryStatus.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(updateAdCategoryStatus.fulfilled, (state, { payload }) => {
        state.loading = false;
        state.responseData = payload.data;

        if (payload.status) {
          state.message = payload.status.message;
          state.responseImpactData = payload.status.data?.active_schedules;
          state.editable_status = payload.status?.editable_status;
          state.warningPagination = payload.status?.data?.active_schedules;
        }
      })
      .addCase(updateAdCategoryStatus.rejected, (state, { payload }) => {
        state.loading = false;
        state.error = payload || "Failed to edit event";
      });
  },
});

export const {
  filterCategory,
  setAdCategoryDialogVisible,
  setAdCategoryModalLoading,
  setSelectedAdCategory,
  setEditItemId,
  setAdCategoryValidationDialogVisible,
} = AdcategorySlice.actions;

export default AdcategorySlice.reducer;
